export function nativeTexture(name) { return UI_TEXTURES[name] || null; }
export function findNativeLayout(bundle, path) { return UI_LAYOUTS.find(r => r.bundle === bundle && r.path === path) || null; }
export function nativeBoundsStyle(row, scale = 2/3, visible = true) {
  if (!row?.screen) throw new Error('Prefab-relative geometry needs an instance placement');
  const [x,y,w,h] = visible ? row.visibleBounds : row.bounds;
  return `left:${x*scale}px;top:${y*scale}px;width:${w*scale}px;height:${h*scale}px;`;
}
